// Prepara a coleta: domínio do site (ou do e-mail corporativo), CNPJ e nome.
const t = $json;
const p = t.payload || {};
const e = p.empresa || {};
const gratuitos = /^(gmail|hotmail|outlook|live|yahoo|bol|uol|terra|icloud|ig)\./i;
const doSite = String(e.site || '').trim().replace(/^https?:\/\//i, '').replace(/^www\./i, '').split(/[\/?#]/)[0].toLowerCase();
const doEmail = String(e.email || '').split('@')[1] || '';
const dominio = doSite || (doEmail && !gratuitos.test(doEmail) ? doEmail.toLowerCase() : '');
return {
  json: {
    trabalho: { id: t.id, negocio_id: t.negocio_id, empresa: e, segmentos: p.segmentos || [], servicos: p.servicos || [], contatos: p.contatos || [] },
    dominio,
    url_site: dominio ? 'https://' + dominio : '',
  },
};

// Extrai do site: texto, e-mails, telefones e CNPJ (rodapés costumam trazer o CNPJ).
const prep = $('Preparar coleta').item.json;
const html = typeof $json.data === 'string' ? $json.data : '';
const texto = html
  .replace(/<script[\s\S]*?<\/script>|<style[\s\S]*?<\/style>|<noscript[\s\S]*?<\/noscript>/gi, ' ')
  .replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/\s+/g, ' ').trim();
const emails = [...new Set((html.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi) || []).map((x) => x.toLowerCase()))]
  .filter((x) => !/\.(png|jpe?g|gif|svg|webp)$/.test(x) && !/(sentry|wixpress|example|exemplo)/.test(x))
  .sort((a, b) => (b.endsWith('@' + prep.dominio) ? 1 : 0) - (a.endsWith('@' + prep.dominio) ? 1 : 0))
  .slice(0, 5);
const telefones = [...new Set((texto.match(/\(?\b\d{2}\)?\s?9?\d{4}[-\s]?\d{4}\b/g) || []).map((x) => x.trim()))].slice(0, 3);
const so = (v) => String(v || '').replace(/\D/g, '');
const cnpjSite = ((texto.match(/\b\d{2}\.?\d{3}\.?\d{3}\/?\d{4}-?\d{2}\b/) || [])[0]) || '';
const cnpj = so(prep.trabalho.empresa.cnpj).length === 14 ? so(prep.trabalho.empresa.cnpj) : (so(cnpjSite).length === 14 ? so(cnpjSite) : '');
return { json: { site_ok: texto.length > 0, texto: texto.slice(0, 6000), emails, telefones, cnpj } };

// Junta as fontes e monta o pedido ao Gemini (sem busca: só classifica e escreve a partir do que foi coletado).
const prep = $('Preparar coleta').item.json;
const site = $('Extrair do site').item.json;
const busca = $('Apollo: buscar decisores').item.json;
const revelado = $('Apollo: revelar decisor').item.json;
const b = $json && $json.razao_social && !$json.error ? $json : null;
const e = prep.trabalho.empresa;
const candidatos = (Array.isArray(busca.people) ? busca.people : []).slice(0, 5).map((x) => ({
  id: x.id, nome: [x.first_name, x.last_name || x.last_name_obfuscated].filter(Boolean).join(' '), cargo: x.title || '',
}));
const pessoa = revelado && revelado.person ? revelado.person : null;
const org = (pessoa && pessoa.organization) || (busca.people && busca.people[0] && busca.people[0].organization) || null;
const coleta = {
  site: { dominio: prep.dominio, lido: site.site_ok, emails: site.emails, telefones: site.telefones, cnpj: site.cnpj },
  apollo: {
    candidatos,
    decisor: pessoa ? { nome: pessoa.name || [pessoa.first_name, pessoa.last_name].filter(Boolean).join(' '), cargo: pessoa.title || '',
      email: pessoa.email || '', linkedin: pessoa.linkedin_url || '' } : null,
    empresa: org ? { nome: org.name || '', setor: org.industry || '', funcionarios: org.estimated_num_employees || null,
      telefone: (org.primary_phone && org.primary_phone.number) || org.phone || '', linkedin: org.linkedin_url || '' } : null,
  },
  cnpj: b,
};
const prompt = [
  'Você é o Enriquecedor da Aprimora, empresa júnior de consultoria em engenharia de produção.',
  'Com base SOMENTE nas informações abaixo (não invente nada), classifique a empresa e escreva hipóteses de dor.',
  '',
  'Empresa: ' + (e.nome || '') + (e.cidade ? ' · ' + e.cidade + (e.uf ? '/' + e.uf : '') : ''),
  'Atividade no CNPJ: ' + (b ? (b.cnae_fiscal_descricao || '') + (b.porte ? ' · porte ' + b.porte : '') : 'não consultado'),
  'Setor no Apollo: ' + ((coleta.apollo.empresa && coleta.apollo.empresa.setor) || 'não encontrado') +
    (coleta.apollo.empresa && coleta.apollo.empresa.funcionarios ? ' · cerca de ' + coleta.apollo.empresa.funcionarios + ' funcionários' : ''),
  'Texto do site: ' + (site.texto ? site.texto.slice(0, 5000) : 'site não lido'),
  '',
  'Segmentos possíveis (escolha um ou ""): ' + prep.trabalho.segmentos.join(', ') + '.',
  'Serviços da Aprimora: ' + prep.trabalho.servicos.join(', ') + '.',
  'hipoteses_dor: até 3 frases curtas, cada uma ligando algo concreto da empresa a um serviço da Aprimora.',
  'resumo: 1 ou 2 frases sobre o que a empresa faz e o porte aparente. Se as informações forem poucas, diga isso.',
].join('\n');
const lista = { type: 'ARRAY', items: { type: 'STRING' } };
return {
  json: {
    coleta,
    corpo: {
      contents: [{ role: 'user', parts: [{ text: prompt }] }],
      generationConfig: {
        temperature: 0.2,
        responseMimeType: 'application/json',
        responseSchema: { type: 'OBJECT', properties: { segmento: { type: 'STRING' }, hipoteses_dor: lista, resumo: { type: 'STRING' } },
          required: ['segmento', 'hipoteses_dor', 'resumo'] },
      },
    },
  },
};

// Monta o resultado para o portal: fatos das fontes (CNPJ > site > Apollo); o Gemini só dá segmento, dores e resumo.
const prep = $('Preparar coleta').item.json;
const { coleta } = $('Montar pedido ao Gemini').item.json;
const c = ($json.candidates || [])[0] || {};
const texto = ((c.content || {}).parts || []).map((p) => p.text || '').join('').trim();
let ia = {};
try { ia = texto ? JSON.parse(texto) : {}; } catch (err) { ia = {}; }
const txt = (v) => (v == null ? '' : String(v).trim());
const titulo = (s) => txt(s).toLowerCase().replace(/(^|\s)\S/g, (l) => l.toUpperCase());
const tel = (v) => { const d = txt(v).replace(/\D/g, '').replace(/^55(?=\d{10,11}$)/, ''); return d.length >= 10 ? '(' + d.slice(0, 2) + ') ' + d.slice(2) : ''; };
const b = coleta.cnpj;
const s = coleta.site;
const ap = coleta.apollo;

const dados = {
  cnpj: b ? txt(b.cnpj) : (s.cnpj || ''),
  razao_social: b ? txt(b.razao_social) : '',
  nome_fantasia: b ? txt(b.nome_fantasia) : '',
  telefone: (b && tel(b.ddd_telefone_1)) || tel(s.telefones[0]) || tel(ap.empresa && ap.empresa.telefone),
  email: txt(b && b.email ? String(b.email).toLowerCase() : s.emails[0]),
  site: prep.dominio ? 'https://' + prep.dominio : '',
  endereco: b ? [titulo(b.descricao_tipo_de_logradouro) + ' ' + titulo(b.logradouro), txt(b.numero), titulo(b.bairro)].map((x) => x.trim()).filter(Boolean).join(', ') : '',
  cidade: b ? titulo(b.municipio) : '',
  uf: b ? txt(b.uf).toUpperCase() : '',
  cnae: b && b.cnae_fiscal ? b.cnae_fiscal + ' · ' + txt(b.cnae_fiscal_descricao) : '',
  porte: b ? txt(b.porte) : '',
  situacao: b ? txt(b.descricao_situacao_cadastral) : '',
};

let decisor = { nome: '', cargo: '', email: '', telefone: '', linkedin: '' };
let origem = '';
if (ap.decisor && ap.decisor.nome) { decisor = { ...decisor, ...ap.decisor }; origem = 'Apollo'; }
else if (b && Array.isArray(b.qsa) && b.qsa.length) {
  const q = b.qsa.find((x) => /administrador/i.test(x.qualificacao_socio || '')) || b.qsa[0];
  if (q && q.nome_socio) { decisor = { ...decisor, nome: titulo(q.nome_socio), cargo: txt(q.qualificacao_socio) }; origem = 'quadro societário (CNPJ)'; }
}
const outros = ap.candidatos.filter((x) => !decisor.nome || !x.nome.startsWith(decisor.nome.split(' ')[0])).map((x) => x.nome + (x.cargo ? ' (' + x.cargo + ')' : ''));

const fontes = [];
if (s.lido) fontes.push('https://' + prep.dominio);
if (b) fontes.push('https://brasilapi.com.br/api/cnpj/v1/' + b.cnpj);
if (ap.candidatos.length || ap.decisor) fontes.push('https://app.apollo.io');
const semIa = !texto ? 'Gemini indisponível nesta busca: segmento e dores ficaram em branco.' : '';
const resumo = [txt(ia.resumo), semIa, origem ? 'Decisor sugerido pelo ' + origem + '.' : '', outros.length ? 'Outros nomes no Apollo: ' + outros.join('; ') + '.' : '']
  .filter(Boolean).join(' ');

return {
  json: {
    trabalho_id: prep.trabalho.id,
    resultado: {
      dados_publicos: dados,
      segmento: txt(ia.segmento),
      decisor,
      emails: s.emails.filter((x) => x !== dados.email).slice(0, 3),
      hipoteses_dor: (Array.isArray(ia.hipoteses_dor) ? ia.hipoteses_dor.map(txt).filter(Boolean) : []).slice(0, 3),
      resumo,
      fontes,
    },
  },
};
